#include "console.h"

#include <stdarg.h>
#include <stdio.h>
#include <string.h>

#include "stm32l4xx_hal.h"

/* Console UART generated by CubeMX. Change here if you route the console
 * elsewhere (e.g. LPUART1). */
extern UART_HandleTypeDef huart2;

#define CONSOLE_TIMEOUT_MS 100U

void console_write(const char *text)
{
    if (text == NULL) {
        return;
    }
    HAL_UART_Transmit(&huart2, (uint8_t *)text, (uint16_t)strlen(text),
                      CONSOLE_TIMEOUT_MS);
}

void console_printf(const char *fmt, ...)
{
    char buf[192];
    va_list args;
    va_start(args, fmt);
    vsnprintf(buf, sizeof(buf), fmt, args);
    va_end(args);
    console_write(buf);
}

void console_format_fixed(char *out, size_t cap, float value, unsigned decimals)
{
    int32_t scale = 1;
    if (decimals == 1U) {
        scale = 10;
    } else if (decimals >= 2U) {
        scale = 100;
    }

    int32_t scaled = (int32_t)(value * (float)scale
                               + (value >= 0.0f ? 0.5f : -0.5f));
    int32_t integer = scaled / scale;
    int32_t frac = scaled % scale;
    if (frac < 0) {
        frac = -frac;
    }

    if (decimals == 1U) {
        snprintf(out, cap, "%ld.%01ld", (long)integer, (long)frac);
    } else if (decimals >= 2U) {
        snprintf(out, cap, "%ld.%02ld", (long)integer, (long)frac);
    } else {
        snprintf(out, cap, "%ld", (long)integer);
    }
}
